#include <CellShard/compiler/grammar/flat_basis_fallback_v1.hh>
#include <cassert>
namespace g=cellshard::compiler::grammar;
int main(){g::typed_grammar_symbol_v1 s[]={{{1,1},{2,1},{2,2},{2,3},{},4,0,g::grammar_symbol_kind_v1::terminal_atom,g::grammar_value_kind_v1::immutable_structure}};g::typed_symbol_table_v1 table{s,1,1,{3,1},5};g::grammar_identity_v1 ids[]={{1,1}};g::flat_basis_contract_v1 basis{ids,1,1,{4,1},{2,1},{2,2},4,0};g::coverage_equation_result_v1 exact{g::coverage_equation_code_v1::exact,1,1};g::derivation_validation_result_v1 receipt{g::derivation_validation_code_v1::validated,{},1};for(std::uint64_t grammar=1;grammar<100;++grammar){auto r=g::select_with_flat_basis_fallback_v1(basis,table,exact,receipt,{5,20,5,5},{5,grammar,5,5});assert(r.selected()&&r.strategy==(grammar+15<35?g::grammar_strategy_v1::explicit_grammar:g::grammar_strategy_v1::flat_basis)&&g::authorizes_execution(r));}exact.code=g::coverage_equation_code_v1::not_exact;assert(g::select_with_flat_basis_fallback_v1(basis,table,exact,receipt,{5,20,5,5},{1,1,1,1}).strategy==g::grammar_strategy_v1::flat_basis);}
